  steps:[{id:'cpu',t:'CPU: cull and sort',d:'draws, state changes'},{id:'sh',t:'Shadow maps',d:'casters redrawn per light'},{id:'dp',t:'Depth pre-pass',d:'optional, cuts overdraw'},{id:'op',t:'Opaque',d:'shader length, fetches'},{id:'at',t:'Alpha test',d:'foliage, cut-outs'},{id:'tr',t:'Transparent',d:'overdraw, blending'},{id:'pp',t:'Post and upscale',d:'full-screen passes'},{id:'ui',t:'UI and present',d:'native resolution'}],
